export type DefaultDialects = "mysql" | "sqlite" | "postgresql" | "mssql";

type SharedOptions = {
	/**
	 * @default false
	 */
	useNumberId?: boolean;
	/**
	 * @default "create"
	 */
	mode?: "create" | "alter";
};

export type CopySchemaOptions = SharedOptions & {
	dialect: DefaultDialects | Resolver;
	conditions?: Record<string, boolean>;
};

export type ResolverHandlerContext = Required<SharedOptions> & {
	schema: DBSchema<false>;
};

export type Resolver = {
	/**
	 * @default "sql"
	 */
	language?: "sql" | "typescript" | "prisma";
	handler: (ctx: ResolverHandlerContext) => string;
};

type LiteralString = "" | (string & Record<never, never>);
type DBFieldType =
	| "string"
	| "number"
	| "boolean"
	| "date"
	| "json"
	| `${"string" | "number"}[]`
	| Array<LiteralString>;

export type DBFieldAttribute = {
	type: DBFieldType;
	/**
	 * If the field should be required on a new record.
	 * @default true
	 */
	required?: boolean;
	/**
	 * Reference to another model.
	 */
	references?: {
		/**
		 * The model to reference.
		 */
		model: string;
		/**
		 * The field on the referenced model.
		 */
		field: string;
		/**
		 * The action to perform when the reference is deleted.
		 * @default "cascade"
		 */
		onDelete?:
			| "no action"
			| "restrict"
			| "cascade"
			| "set null"
			| "set default";
	};
	unique?: boolean;
	/**
	 * If the field should be a bigint on the database instead of integer.
	 */
	bigint?: boolean;
	/**
	 * The name of the field on the database.
	 */
	fieldName: string;
	/**
	 * If the field should be sortable.
	 *
	 * applicable only for `text` type.
	 * It's useful to mark fields varchar instead of text.
	 */
	sortable?: boolean;
};

export type DBSchema<WithCondition extends boolean = true> = {
	/**
	 * The name of the table in the database
	 */
	modelName: string;
	/**
	 * The fields of the table
	 */
	fields: (DBFieldAttribute &
		(WithCondition extends true
			? {
					condition?: string;
				}
			: {}))[];
};
import type { DBFieldAttribute } from "./types";

export function getTypeFactory(
	getTypeMap: (
		field: DBFieldAttribute,
	) => Record<
		"string" | "boolean" | "number" | "date" | "json" | "id" | "foreignKeyId",
		string
	> &
		Partial<Record<"string[]" | "number[]", string>>,
	config?: {
		/**
		 * @default "jsonb"
		 */
		arrayDataType?: "jsonb" | "text";
	},
) {
	return (field: DBFieldAttribute) => {
		const type = field.type;
		const typeMap = getTypeMap(field);
		if (field.fieldName === "id" || field.references?.field === "id") {
			if (field.fieldName === "id") {
				return typeMap.id;
			}
			return typeMap.foreignKeyId;
		}

		if (type === "string[]" || type === "number[]") {
			if (typeMap[type] !== undefined) {
				return typeMap[type];
			}
			return config?.arrayDataType ?? "jsonb";
		}
		if (Array.isArray(type)) {
			return "text";
		}
		return typeMap[type as keyof typeof typeMap]!;
	};
}

export function filterForeignKeys({ fields }: { fields: DBFieldAttribute[] }) {
	return fields.filter(({ references }) => !!references);
}

export function capitalize(str: string) {
	return str.charAt(0).toUpperCase() + str.slice(1);
}
import { mssqlResolver } from "./dialects/mssql";
import { mysqlResolver } from "./dialects/mysql";
import { postgresqlResolver } from "./dialects/postgresql";
import { sqliteResolver } from "./dialects/sqlite";
import type {
	CopySchemaOptions,
	DBSchema,
	DefaultDialects,
	Resolver,
	ResolverHandlerContext,
} from "./types";

const defaultResolvers: Record<DefaultDialects, Resolver> = {
	mysql: mysqlResolver,
	sqlite: sqliteResolver,
	postgresql: postgresqlResolver,
	mssql: mssqlResolver,
};

const defaultModels = ["user", "session", "account", "verification"];

export const copySchema = <
	const S extends DBSchema,
	O extends CopySchemaOptions,
>(
	schema: S,
	options: O,
) => {
	const conditions = new Set<string>();
	const resolver =
		typeof options.dialect !== "string"
			? options.dialect
			: defaultResolvers[options.dialect];

	const filteredSchema = {
		...schema,
		fields: schema.fields.filter((field) => {
			const condition = field.condition;
			if (condition === undefined || condition === "") {
				return true;
			}
			conditions.add(condition);
			return options.conditions?.[condition] ?? false;
		}),
	};

	let mode = options.mode;
	if (!mode) {
		mode = defaultModels.includes(filteredSchema.modelName)
			? "alter"
			: "create";
	}

	const ctx: ResolverHandlerContext = {
		useNumberId: options.useNumberId ?? false,
		mode,
		schema: filteredSchema,
	};

	return {
		result: resolver.handler(ctx),
		language: resolver.language ?? "sql",
	};
};

