import { getGeneratedDatabaseIndexName } from "../../../packages/core/src/db/database-index-name";
import type { DBFieldAttribute, DBSchema, DefaultDialects } from "./types";

export function getTypeFactory(
	getTypeMap: (
		field: DBFieldAttribute,
	) => Record<
		"string" | "boolean" | "number" | "date" | "json" | "id" | "foreignKeyId",
		string
	> &
		Partial<Record<"string[]" | "number[]", string>>,
	config?: {
		/**
		 * @default "jsonb"
		 */
		arrayDataType?: "jsonb" | "text";
	},
) {
	return (field: DBFieldAttribute) => {
		const type = field.type;
		const typeMap = getTypeMap(field);
		if (field.fieldName === "id" || field.references?.field === "id") {
			if (field.fieldName === "id") {
				return typeMap.id;
			}
			return typeMap.foreignKeyId;
		}

		if (type === "string[]" || type === "number[]") {
			if (typeMap[type] !== undefined) {
				return typeMap[type];
			}
			return config?.arrayDataType ?? "jsonb";
		}
		if (Array.isArray(type)) {
			return field.index && !field.unique ? typeMap.string : "text";
		}
		return typeMap[type as keyof typeof typeMap]!;
	};
}

export function filterForeignKeys({ fields }: { fields: DBFieldAttribute[] }) {
	return fields.filter(({ references }) => !!references);
}

export function capitalize(str: string) {
	return str.charAt(0).toUpperCase() + str.slice(1);
}

/** Returns a portable index name using physical table and column names. */
export function getIndexName(tableName: string, fieldName: string) {
	return getGeneratedDatabaseIndexName(tableName, [fieldName]);
}

/** Quotes a string literal used in SQL catalog lookups or dynamic SQL. */
export function sqlString(value: string) {
	return `'${value.replaceAll("'", "''")}'`;
}

/** Generates non-unique indexes after the table's columns have been declared. */
export function getSQLIndexes(
	schema: DBSchema<false>,
	dialect: DefaultDialects,
) {
	const quote = (value: string) => {
		if (dialect === "mysql") return `\`${value.replaceAll("`", "``")}\``;
		if (dialect === "mssql") return `[${value.replaceAll("]", "]]")}]`;
		return `"${value.replaceAll('"', '""')}"`;
	};
	return schema.fields
		.filter((field) => field.index && !field.unique)
		.map((field) => {
			const name = getIndexName(schema.modelName, field.fieldName);
			const create = `CREATE INDEX ${quote(name)} ON ${quote(schema.modelName)} (${quote(field.fieldName)});`;
			if (dialect === "mysql") {
				return [
					`SET @better_auth_index_sql = (SELECT IF(`,
					`  EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name = ${sqlString(schema.modelName)})`,
					`  AND NOT EXISTS (SELECT 1 FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = ${sqlString(schema.modelName)} AND index_name = ${sqlString(name)}),`,
					`  ${sqlString(create)}, 'SELECT 1'));`,
					`PREPARE better_auth_index_stmt FROM @better_auth_index_sql;`,
					`EXECUTE better_auth_index_stmt;`,
					`DEALLOCATE PREPARE better_auth_index_stmt;`,
				].join("\n");
			}
			if (dialect === "mssql") {
				const object = `OBJECT_ID(${sqlString(quote(schema.modelName))}, 'U')`;
				return `IF ${object} IS NOT NULL AND NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = ${object} AND name = ${sqlString(name)})\nBEGIN\n\t${create}\nEND;`;
			}
			return `CREATE INDEX IF NOT EXISTS ${quote(name)} ON ${quote(schema.modelName)} (${quote(field.fieldName)});`;
		});
}
	const toBeAdded: {
		table: string;
		fields: Record<string, DBFieldAttribute>;
		order: number;
	}[] = [];
	const toBeAddedIndexes: {
		table: string;
		index: ResolvedDBTableIndex;
		name: string;
	}[] = [];
	const plannedIndexes = new Map<string, ResolvedDBTableIndex>();

	for (const [key, value] of Object.entries(betterAuthSchema)) {
		if (value.disableMigrations) {
			continue;
		}
		const table = tableMetadata.find((table) => table.name === key);
		// Existing columns can gain field-level index hints after their creation.
		// New tables and new columns already schedule these indexes below.
		const existingFieldIndexes: ResolvedDBTableIndex[] = table
			? Object.entries(value.fields)
					.filter(
						([fieldName, field]) =>
							field.index &&
							!field.unique &&
							table.columns.some((column) => column.name === fieldName),
					)
					.map(([fieldName]) => ({
						columns: [fieldName],
						name: getDatabaseFieldIndexName(key, fieldName, false),
						unique: false,
					}))
			: [];
		for (const index of [...(value.indexes ?? []), ...existingFieldIndexes]) {
			const name = index.name;
			const indexKey = createDatabaseIndexKey(key, name);
			const existingIndex = databaseIndexes.get(indexKey);
			if (existingIndex) {
				if (!databaseIndexMatches(existingIndex, index)) {
					throw new BetterAuthError(
						`Database index "${name}" on table "${key}" does not match the configured fields and uniqueness. Rename or replace the existing index, then run the migration again.`,
					);
				}
				continue;
			}
			if (dbType === "sqlite" || dbType === "postgres") {
				const indexOnAnotherTable = [...databaseIndexes.values()].find(
					(databaseIndex) =>
						getPortableDatabaseIdentifierKey(databaseIndex.name) ===
							getPortableDatabaseIdentifierKey(name) &&
						getPortableDatabaseIdentifierKey(databaseIndex.table) !==
							getPortableDatabaseIdentifierKey(key),
				);
				if (indexOnAnotherTable) {
					throw new BetterAuthError(
						`Database index name "${name}" is already used by table "${indexOnAnotherTable.table}". Index names must be unique across the schema.`,
					);
				}
			}
			const plannedIndex = plannedIndexes.get(indexKey);
			if (plannedIndex) {
				const plannedDefinition: DatabaseIndexDefinition = {
					columns: plannedIndex.columns,
					name: plannedIndex.name,
					table: key,
					unique: plannedIndex.unique ?? false,
					validFullColumns: true,
				};
				if (!databaseIndexMatches(plannedDefinition, index)) {
					throw new BetterAuthError(
						`Database index name "${name}" identifies more than one index on table "${key}".`,
					);
				}
				continue;
			}
			if (table && (dbType === "mysql" || dbType === "mssql")) {
				assertExistingTableIndexFits({
					columnBounds: databaseColumnBounds,
					dbType,
					existingColumns: new Set(table.columns.map((column) => column.name)),
					fields: value.fields,
					index,
					indexes: value.indexes ?? [],
					table: key,
				});
			}
			plannedIndexes.set(indexKey, index);
			toBeAddedIndexes.push({ table: key, index, name });
		}
		if (!table) {
			const tIndex = toBeCreated.findIndex((t) => t.table === key);
			const tableData = {
				table: key,
				fields: value.fields,
				order: value.order || Infinity,
			};

